import json
import itertools

# Events in the competition
events = ['run', 'sprint', 'high', 'long', 'shot']

def valid_choice(s):
    # Each grade chooses one or two events
    if not (1 <= len(s) <= 2):
        return False
    # Running excludes sprint and long jump
    if 'run' in s and (s & {'sprint', 'long'}):
        return False
    # Long jump excludes running and shot put
    if 'long' in s and (s & {'run', 'shot'}):
        return False
    return True

# All valid event choices for a grade that has chosen long-distance running
run_choices = []
for k in (1, 2):
    for combo in itertools.combinations(events, k):
        s = set(combo)
        if 'run' in s and valid_choice(s):
            run_choices.append(frozenset(s))

# Options, read as "the grade chooses at least one of these events"
options = {
    'A': {'sprint', 'shot'},
    'B': {'sprint', 'long'},
    'C': {'shot', 'high'},
    'D': {'run', 'high'},
}

possible = {}
for key, opt in options.items():
    possible[key] = any(s & opt for s in run_choices)

impossible = sorted(k for k, ok in possible.items() if not ok)

if len(impossible) == 1:
    final_answer = impossible[0]
else:
    final_answer = "UNSUPPORTED"

result = {
    "final_answer": final_answer,
    "evidence": {
        "run_valid_choices": sorted(sorted(s) for s in run_choices),
        "option_possible": possible,
        "impossible_options": impossible,
    },
}
print(json.dumps(result, separators=(",", ":")))
